using System;using System.Globalization;
namespace PeakMp3Win7{internal static class OracleModel{static void Main(){AnalogMeterChannel l=new AnalogMeterChannel(),r=new AnalogMeterChannel();string line;int frame=0;Console.WriteLine("frame,input_left,input_right,angle_left,angle_right,level_left,level_right,delta_left,target_left");while((line=Console.ReadLine())!=null){string[] s=line.Split(' ');float a=float.Parse(s[0],CultureInfo.InvariantCulture),b=float.Parse(s[1],CultureInfo.InvariantCulture);l.Tick(a);r.Tick(b);Console.WriteLine(string.Join(",",new string[]{(frame++).ToString(),a.ToString("R",CultureInfo.InvariantCulture),b.ToString("R",CultureInfo.InvariantCulture),l.Angle.ToString("R",CultureInfo.InvariantCulture),r.Angle.ToString("R",CultureInfo.InvariantCulture),l.Level.ToString("R",CultureInfo.InvariantCulture),r.Level.ToString("R",CultureInfo.InvariantCulture),l.Delta.ToString("R",CultureInfo.InvariantCulture),l.Target.ToString("R",CultureInfo.InvariantCulture)}));}}}}
